import { test, expect } from '@playwright/test';

test.describe('Unsaved Form Navigation Warning', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/form');
  });

  test('should display warning and prevent navigation when form is unsaved', async ({ page }) => {
    // Fill form fields
    const nameInput = page.getByLabel('Full Name');
    await nameInput.fill('John Doe');

    const emailInput = page.getByLabel('Email Address');
    await emailInput.fill('john@example.com');

    // Click save button to mark as saved
    const saveButton = page.getByRole('button', { name: /save/i });
    await saveButton.click();

    // Verify form is saved
    const savedMessage = page.getByText('Form saved successfully');
    await expect(savedMessage).toBeVisible();

    // Clear form to make it unsaved again
    await nameInput.clear();
    await emailInput.clear();

    // Verify form is now unsaved
    const unsavedIndicator = page.getByText('Unsaved changes');
    await expect(unsavedIndicator).toBeVisible();

    // Attempt to navigate away
    const navigateButton = page.getByRole('button', { name: /navigate/i });
    await navigateButton.click();

    // Verify warning modal appears
    const warningModal = page.locator('[data-testid="unsaved-warning-modal"]');
    await expect(warningModal).toBeVisible();

    const warningMessage = page.getByText('You have unsaved changes');
    await expect(warningMessage).toBeVisible();

    // Verify warning button is visible
    const warningConfirmButton = page.getByRole('button', { name: /leave/i });
    await expect(warningConfirmButton).toBeVisible();

    // Verify cancel button is visible
    const warningCancelButton = page.getByRole('button', { name: /cancel/i });
    await expect(warningCancelButton).toBeVisible();

    // Click cancel to stay on form
    await warningCancelButton.click();

    // Verify warning modal is closed
    await expect(warningModal).not.toBeVisible();

    // Verify form data is still present
    await expect(nameInput).toHaveValue('John Doe');
    await expect(emailInput).toHaveValue('john@example.com');
  });

  test('should allow navigation when form is saved', async ({ page }) => {
    // Fill form fields
    const nameInput = page.getByLabel('Full Name');
    await nameInput.fill('Jane Smith');

    const emailInput = page.getByLabel('Email Address');
    await emailInput.fill('jane@example.com');

    // Click save button
    const saveButton = page.getByRole('button', { name: /save/i });
    await saveButton.click();

    // Verify form is saved
    const savedMessage = page.getByText('Form saved successfully');
    await expect(savedMessage).toBeVisible();

    // Attempt to navigate away
    const navigateButton = page.getByRole('button', { name: /navigate/i });
    await navigateButton.click();

    // Verify warning modal does not appear
    const warningModal = page.locator('[data-testid="unsaved-warning-modal"]');
    await expect(warningModal).not.toBeVisible();

    // Verify navigation proceeds
    await expect(page).toHaveURL(/.*\/dashboard/);
  });
});
